fn calculate_flow_rate(pressure_pa: f64, temperature_k: f64, diameter_mm: f64) -> f64 {
    let diameter_m = diameter_mm / 1000.0;
    let area = std::f64::consts::PI * (diameter_m / 2.0).powi(2);
    let gas_constant = 2077.0;
    let density = pressure_pa / (gas_constant * temperature_k);
    let velocity = (2.0 * pressure_pa / density).sqrt();
    area * velocity
}
```
