function calculateSeasonalMean(readings: ClimateReading[], season: string): number {
  const filtered = readings.filter(r => getSeasonFromDate(r.timestamp) === season);
  const sum = filtered.reduce((acc, r) => acc + r.temperature, 0);
  return filtered.length > 0 ? sum / filtered.length : 0;
