```javascript
function calculateSurfaceTemperature(latitude, timeOfDay) {
  const baseSolarIntensity = 9100; // W/m² at Neptune's orbit
  const nightSideCelsius = -180;
  const dayMultiplier = Math.cos(latitude * Math.PI / 180);
  const timeFactors = (Math.cos(timeOfDay * Math.PI / 12) + 1) / 2;
  const adjustedIntensity = baseSolarIntensity * dayMultiplier * timeFactors;
  const temperature = nightSideCelsius + (adjustedIntensity / 50);
  return Math.round(temperature);
}
